# Обработчик сохранения таблицы 6110.1 (per‑user saving)
observeEvent(input$save_table6110_1, {
  if (!r$user_authenticated) {
    shinyalert("Ошибка", "Для сохранения необходимо авторизоваться.", type = "error")
    return()
  }
  
  if (!r$db_initialized) {
    shinyalert("Ошибка", "База данных недоступна. Невозможно сохранить таблицу.", type = "error")
    return()
  }
  
  current_session <- session_id()
  
  # Получаем текущие данные из таблицы (merged view)
  if (!is.null(input$table6110.1Item1)) {
    tryCatch({
      # Обновляем данные из таблицы
      new_df <- hot_to_r(input$table6110.1Item1)
      validation_result <- validate_operation_dates(new_df)
      if (!validation_result$valid) {
        data$df6110.1 <- validation_result$df
      } else {
        data$df6110.1 <- new_df
      }
    }, error = function(e) {
      message("Ошибка при обновлении данных из таблицы 6110.1: ", e$message)
    })
  }
  
  # Filter to keep only rows belonging to the current user
  user_df <- data$df6110.1[data$df6110.1$Пользователь == r$current_user, ]
  
  # If the user has no rows, it saves an empty data frame (which will delete all their rows)
  # This handles the case where the user deleted all rows they owned
  
  # Save using the per‑user function (deletes only this user's rows, then inserts their current rows)
  success <- save_data_simple(user_df, "app_data_6110_1", current_session, r$current_user)
  
  if (success) {
    shinyalert("Успех", paste("Данные таблицы 6110.1 сохранены для пользователя", r$current_user), type = "success")
    r$data_version <- r$data_version + 1
    
    # Обновляем timestamp
    update_info <- get_last_update(current_session)
    if (!is.null(update_info)) {
      r$current_session_last_update <- update_info$timestamp
    }
  } else {
    shinyalert("Ошибка", "Не удалось сохранить данные таблицы 6110.1.", type = "error")
  }
})
  
