      	selectdates6230.1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df6230.1_2 <- data$df6230.1[as.Date(data$df6230.1$"Дата операции") %in% selectdates6230.1_3 & data$df6230.1$"Счет № статьи дохода" == input$text, ]
