# Обработчик для кнопки "Загрузить отмеченные таблицы"
observeEvent(input$load_selected_btn, {
  req(input$data_load_date)
  
  # Проверяем, выбрана ли хотя бы одна таблица
  if (!any(c(input$check_6110_1, input$check_6110_2,
             input$check_6120_1, input$check_6120_2,
             input$check_6130_1, input$check_6130_2,
             input$check_6141_1, input$check_6141_2,
             input$check_6142_1, input$check_6142_2,
             input$check_6143,
             input$check_6150, input$check_6160,
	     input$check_6171, input$check_6172,
             input$check_6210_1, input$check_6210_2,
             input$check_6220_1, input$check_6220_2,
             input$check_6230_1, input$check_6230_2,
             input$check_6240_1, input$check_6240_2,
             input$check_6250_1, input$check_6250_2,
             input$check_6261_1, input$check_6261_2,
             input$check_6262_1, input$check_6262_2,
             input$check_6263_1, input$check_6263_2,
             input$check_6264_1, input$check_6264_2,
             input$check_6271_1, input$check_6271_2,
             input$check_6272_1, input$check_6272_2,
             input$check_6273, input$check_6274,
             input$check_6275_1, input$check_6275_2,
             input$check_6276_1, input$check_6276_2,
             input$check_6277_1, input$check_6277_2))) {
    shinyalert("Ошибка", "Не выбрана ни одна таблица для загрузки.", type = "error")
    return()
  }
  
  r$show_loading <- TRUE
  
  tryCatch({
    # Загружаем данные выбранных таблиц
    tables_data <- load_selected_tables_data(input$data_load_date)
    
    # Проверяем, есть ли данные
    if (length(tables_data) == 0) {
      shinyalert("Информация", "Нет данных для выбранных таблиц и даты.", type = "info")
      return()
    }
    
    # Создаем временную директорию для файлов
    temp_dir <- tempdir()
    zip_file <- file.path(temp_dir, paste0("selected_tables_", format(input$data_load_date, "%Y-%m-%d"), ".zip"))
    
    # Создаем список файлов для архивации
    files_to_zip <- c()
    
    # Сохраняем каждую таблицу в отдельный файл Excel
    for (table_name in names(tables_data)) {
      if (!is.null(tables_data[[table_name]])) {
        # Преобразуем данные в нужный формат
        df <- as.data.table(tables_data[[table_name]])
        
        # Устанавливаем правильные имена столбцов в зависимости от таблицы
        if (table_name == "df6110.1") {
          expected_cols <- c("operation_date", "operation_time", "document_number", "income_account",
                             "operation_description", "accounting_method", "initial_balance", 
                             "credit", "debit", "correspondence_debit", "correspondence_credit", "final_balance", "username")
          
          if (all(expected_cols %in% names(df))) {
            setnames(df, expected_cols,
                     c("Дата операции", "Время проводки", 
		       "Номер первичного документа", "Счет № статьи дохода",
                       "Содержание операции", "Метод учета",
                       "Сальдо начальное", "Кредит", "Дебет", 
